with gaps as (select *, case when paid_at - lag(paid_at) over (partition by order_id order by paid_at, id) > interval 60 days then 1 else 0 end as new_group_flag from payments), islands as (select *, sum(new_group_flag) over (partition by order_id order by paid_at, id rows between unbounded preceding and current row) as island_id from gaps) select date_trunc('year', paid_at) as year_start, size(collect_set(status)) as num_status, count(distinct method) as distinct_methods, count(*) as cnt, count(*) filter (where method = 'cash') as cash_rows, round(avg(island_id), 2) as avg_island_id from islands group by year_start having avg_island_id < 0 order by cash_rows desc nulls first
